\begin{tikzpicture}[scale=0.6]
\draw[step=1,gray!25,very thin] (0,0) grid (6,6);
\draw[->] (0,0)--(6.5,0) node[right,font=\scriptsize]{kg};
\draw[->] (0,0)--(0,6.5) node[above,font=\scriptsize]{lb};
\node[below,font=\scriptsize] at (1,0) {$2$};\node[below,font=\scriptsize] at (2,0) {$4$};\node[below,font=\scriptsize] at (3,0) {$6$};\node[below,font=\scriptsize] at (4,0) {$8$};\node[below,font=\scriptsize] at (5,0) {$10$};\node[below,font=\scriptsize] at (6,0) {$12$};
\node[left,font=\scriptsize] at (0,1) {$4$};\node[left,font=\scriptsize] at (0,2) {$8$};\node[left,font=\scriptsize] at (0,3) {$12$};\node[left,font=\scriptsize] at (0,4) {$16$};\node[left,font=\scriptsize] at (0,5) {$20$};\node[left,font=\scriptsize] at (0,6) {$24$};
